"use strict";
import { useMemo } from "react";
import { useQuery } from "@tanstack/react-query";
import { useAccount } from "hooks/useAccount";
import { usePublicClient } from "wagmi";
import {
  fetchVotingRewardsBatch
} from "./useVotingRewardsFromSubgraph";
export function useEnhanceVotingRewardsWithMulticall(locks, chainIdOverride) {
  const { chainId: connectedChainId } = useAccount();
  const publicClient = usePublicClient();
  const chainId = chainIdOverride ?? connectedChainId;
  const tokenIds = useMemo(
    () => Array.from(
      new Set(
        (locks ?? []).map((lock) => lock.id).filter((id) => typeof id === "string" && id.length > 0)
      )
    ).sort(),
    [locks]
  );
  const enabled = Boolean(publicClient && chainId && tokenIds.length > 0);
  const query = useQuery({
    queryKey: ["voting-rewards-batch-onchain", chainId, tokenIds],
    queryFn: () => fetchVotingRewardsBatch(tokenIds, chainId, publicClient),
    enabled,
    refetchInterval: 3e4,
    staleTime: 15e3
  });
  const baseError = query.error ?? null;
  const baseIsLoading = enabled ? query.isLoading : false;
  const results = useMemo(() => {
    const data = query.data ?? {};
    const map = {};
    tokenIds.forEach((tokenId) => {
      const entry = data[tokenId];
      map[tokenId] = {
        votedPools: entry?.votedPools ?? [],
        rewards: entry?.rewards ?? [],
        canClaim: entry?.canClaim ?? false,
        isLoading: baseIsLoading,
        error: baseError,
        usedVeAbx: entry?.usedVeAbx ?? "0",
        refetch: query.refetch
      };
    });
    return map;
  }, [tokenIds, query.data, baseIsLoading, baseError, query.refetch]);
  return {
    results,
    isLoading: baseIsLoading,
    error: baseError,
    refetch: query.refetch
  };
}
